//! Golden test of the geometry. `fixtures/golden.json` was generated by the ORIGINAL code (Rocket 0.4,
//! nightly-2020-12-15, the `create_triangles` + `tris_to_binary_stl` pair) from `fixtures/cases.json`,
//! so passing shows the port and the dependency upgrades did not change the output.
//! The hash is of the whole binary STL (NaN bit patterns normalised: the original also emits a few NaN
//! triangles for the `thick_everywhere_holes` input, and NaN sign bits differ between compilers); the triangle count and bounding box are there to make a
//! failure easier to read.
mod common;
use sha2::{Digest, Sha256};

#[test]
fn stl_output_matches_the_original_implementation() {
    let golden = common::golden();
    let cases = common::cases();
    assert_eq!(cases.len(), golden.as_object().unwrap().len());
    for case in cases {
        let name = case.name.clone();
        let expected = &golden[&name];
        let params = case.params();
        let tris = server::create_triangles(case.data(), &params).unwrap();
        let stl = server::tris_to_binary_stl(tris);
        let (n, min, max) = common::stl_summary(&stl);
        assert_eq!(n as u64, expected["triangles"].as_u64().unwrap(), "{name}: triangle count");
        for k in 0..3 {
            assert!((min[k] as f64 - expected["bbox_min"][k].as_f64().unwrap()).abs() < 1e-6, "{name}: bbox min {k}");
            assert!((max[k] as f64 - expected["bbox_max"][k].as_f64().unwrap()).abs() < 1e-6, "{name}: bbox max {k}");
        }
        assert_eq!(stl.len() as u64, expected["bytes"].as_u64().unwrap(), "{name}: byte length");
        let (canon, nans) = common::canonical_nans(&stl);
        assert_eq!(nans as u64, expected["nan_floats"].as_u64().unwrap(), "{name}: NaN count");
        let hash = format!("{:x}", Sha256::digest(&canon));
        assert_eq!(hash, expected["sha256_nan_canonical"].as_str().unwrap(), "{name}: STL bytes differ from the original");
    }
}
